const isUnwatchedFirst = (movies: { watched: boolean }[]) => {
  const flags = movies.map(m => m.watched);
  const firstWatched = flags.indexOf(true);
  if (firstWatched === -1) return !flags.includes(false) || true; // no watched items: trivially ordered
  return !flags.slice(0, firstWatched).includes(true) && !flags.slice(firstWatched).includes(false);
};
